"""Dirección visual: Fase 3/4 Lumine, alternancia clara/oscura y acento celeste."""

def visual(s,base):
 k=s['id']
 if k=='gancho':return '''<div class="hero-bg"><img src="img/portada-rayos.jpg" alt="Ilustración conceptual de Lumine"></div><div class="portada-copy"><div class="eyebrow">IA APLICADA / ESTIMADOR DE AHORRO</div><h1>¿CUÁNTO TE VAS<br><em>a ahorrar?</em></h1><div class="intro-deck">Una estimación personal.<br>Una promesa que se puede comprobar.</div></div><div class="cover-identity"><b>Diego Alarcón · Benjamín Torres · Lukas Verdugo</b><br>Grupo 1 · NRC 4153 · Universidad Andrés Bello<br>Prof. Cristián R. Cisterna-Aravena</div><div class="illust">Ilustración conceptual del producto</div>'''
 if k=='error':return '''<div class="eyebrow">EL PROBLEMA / PROMESA COMERCIAL</div><h1>UNA CIFRA PARA TODOS<br><em>se equivoca.</em></h1><div class="comparison"><div class="comparison-bars"><div class="compare-row"><div><span>Promesa genérica de 25%</span><b>7,90 <small>pp</small></b></div><div class="rail"><i style="width:100%"></i></div></div><div class="compare-row selected"><div><span>Modelo Ridge</span><b>0,77 <small>pp</small></b></div><div class="rail"><i style="width:9.75%"></i></div></div><div class="chart-caption">ERROR ABSOLUTO MEDIO · MENOS ES MEJOR</div></div><div class="comparison-proof"><strong>≈10×</strong><span>MENOS ERROR</span><p>En conductores<br>simulados no vistos.</p></div></div><div class="data-note">Prueba del modelo. El ahorro físico del kit sigue pendiente.</div>'''
 if k=='evidencia':return '''<div class="eyebrow">METODOLOGÍA / QUÉ RESPALDA LA CIFRA</div><h1>CONDUCIR ES REAL.<br><em>El ahorro se simula.</em></h1><div class="evidence-grid"><div><span class="eyebrow">ENTRENAMIENTO</span><strong>300</strong><h2>Conductores<br>sintéticos</h2><p>Dos semanas por conductor.</p></div><div class="highlight"><span class="eyebrow">CONTRASTE EXTERNO</span><strong>45</strong><h2>Jornadas reales<br>secundarias</h2><p>21 vehículos · Otra ciudad.</p></div><div class="unvalidated"><span class="eyebrow">PRÓXIMA VALIDACIÓN</span><strong>0</strong><h2>Kits con ahorro<br>medido</h2><p>Falta telemetría en Santiago.</p></div></div><div class="evidence-bridge"><span>PATRÓN DE CONDUCCIÓN</span><b>→</b><strong>SIMULADOR</strong><b>→</b><span>AHORRO ESTIMADO</span></div>'''
 if k=='pregunta':return '''<div class="decision-bg"><img src="img/producto-kit.jpg" alt="Ilustración conceptual del kit"></div><div class="eyebrow">PREGUNTA DE INVESTIGACIÓN / DOS RESPUESTAS</div><h1>PODEMOS ESTIMAR.<br><em>Falta probar si vende.</em></h1><div class="question-states"><div><span class="status-dot"></span><div><small>PRECISIÓN</small><h2>Evidencia computacional</h2><p>Modelo, prototipo y gobernanza.</p></div></div><div><span class="status-dot pending"></span><div><small>ADOPCIÓN</small><h2>Efecto comercial pendiente</h2><p>H3 debe medirse con un A/B.</p></div></div></div><div class="illust">Ilustración conceptual · Implementar con ajustes</div>'''
 if k=='arquitectura':return '''<div class="eyebrow">LA SOLUCIÓN / MATEMÁTICA + LENGUAJE</div><h1>CADA CIFRA SE CALCULA<br><em>una sola vez.</em></h1><div class="unit-hero"><img src="img/ventaja-unidad.jpg" alt="Ilustración conceptual de una unidad de control"><span>ILUSTRACIÓN CONCEPTUAL</span></div><div class="system-flow"><div><b>01</b><h2>SIMULAR</h2><p>Energía recuperable</p></div><i>↓</i><div><b>02</b><h2>PREDECIR</h2><p>Ridge · 11 variables</p></div><i>↓</i><div><b>03</b><h2>TRADUCIR</h2><p>Pesos y plazo</p></div><i>↓</i><div class="accent"><b>04</b><h2>EXPLICAR</h2><p>Claude + RAFA</p></div></div><div class="system-rule"><strong>VALI­DADOR + TÉCNICO</strong><span>El lenguaje copia las cifras; una persona supervisa.</span></div>'''
 if k=='caso':return '''<div class="eyebrow">PROTOTIPO / CASO N1 · COLECTIVO DE 213 KM AL DÍA</div><h1>EL AHORRO,<br><em>para tu forma de manejar.</em></h1><div class="case-car"><img src="img/producto-kit.jpg" alt="Ilustración conceptual del producto"><span>CASO SINTÉTICO · SUPUESTOS DEL RAMO IA</span></div><div class="diagnostic"><div class="diagnostic-top"><span>DIAGNÓSTICO N1</span><b>ESTIMACIÓN</b></div><div class="diagnostic-num">19,7<span>%</span></div><div class="diagnostic-range"><span>18,4%</span><i><b></b></i><span>21,0%</span></div><div class="diagnostic-values"><div><strong>$159.000</strong><span>AHORRO MENSUAL</span></div><div><strong>22 <small>meses</small></strong><span>PLAZO CONSERVADOR</span></div></div><div class="diagnostic-foot">Ridge + plantilla de respaldo</div></div>'''
 if k=='cobertura':
  def ring(v,kind):
   import math
   c=2*math.pi*145
   return f'<svg viewBox="0 0 400 400"><circle class="ring-base" cx="200" cy="200" r="145"/><circle class="ring-value {kind}" cx="200" cy="200" r="145" stroke-dasharray="{c*v/100} {c}" transform="rotate(-90 200 200)"/><text x="200" y="218" text-anchor="middle">{v}<tspan>%</tspan></text></svg>'
  return '<div class="eyebrow">VALIDACIÓN EXTERNA / LA PRUEBA MÁS EXIGENTE</div><h1>EL INTERVALO TAMBIÉN<br><em>tiene que aprobar.</em></h1><div class="coverage-instruments"><div>'+ring(36,'low')+'<h2>Solo sintéticos</h2></div><div class="recalibrate"><span>REAJUSTE CON<br>DATOS REALES</span><b>→</b><p>Objetivo: 80%</p></div><div>'+ring(78,'high')+'<h2>Tras el reajuste</h2></div></div><div class="data-note">45 jornadas de conducción real. El ahorro objetivo se calcula por simulación.</div>'
 if k=='rafa':return '''<div class="eyebrow">RAFA / INSTRUCCIONES, ITERACIÓN Y CONTROL</div><h1>LAS INSTRUCCIONES<br><em>también se probaron.</em></h1><div class="prompt-panel"><span>ENTRADA</span><code>{ estado, cifras_formateadas }</code><div class="rafa-four"><b>R</b><b>A</b><b>F</b><b>A</b></div><p>Rol · Acción · Formato · Antecedentes</p><div class="copy-rule">COPIAR LAS CIFRAS.<br><em>Nunca calcular.</em></div></div><div class="prompt-evidence"><strong>12<span>/12</span></strong><label>CASOS APROBADOS · v3.1</label><div class="versions-line"><span>v1<br><b>0/12</b></span><i>→</i><span>v2<br><b>4/12</b></span><i>→</i><span>v3<br><b>11/12</b></span></div><div class="redteam"><b>10/10</b><p>ataques resistidos en ChatGPT<br>tras revisión humana</p></div></div><div class="data-note">Una ejecución por caso. Repetir la batería ante cada cambio.</div>'''
 if k=='trazabilidad':return '''<div class="eyebrow">CONSTRUCCIÓN / USO TRAZABLE DE IA</div><h1>CADA CAMBIO<br><em>deja una huella.</em></h1><div class="git-flow"><div class="git-labels"><div><small>CONSTRUCCIÓN</small><h2>Claude Code</h2><p>Simulador, prototipo e informes.</p></div><div><small>INTEGRACIÓN</small><h2>Codex</h2><p>Ridge, pruebas y reproducción.</p></div></div><svg class="branches" viewBox="0 0 750 340"><path d="M30 55H280Q360 55 420 170H700"/><path d="M30 285H280Q360 285 420 170"/><circle cx="70" cy="55" r="11"/><circle cx="210" cy="55" r="11"/><circle cx="70" cy="285" r="11"/><circle cx="210" cy="285" r="11"/><circle cx="450" cy="170" r="16"/></svg><div class="merge-gate">EL EQUIPO REVISA E INTEGRA</div></div><div class="test-proof"><strong>20<span>/20</span></strong><label>PRUEBAS AUTOMÁTICAS</label><p>En la integración documentada.</p><div>Cinco IA auditoras.<br>Cada hallazgo se contrasta.</div></div>'''
 if k=='gobernanza':return '''<div class="eyebrow">GOBERNANZA / QUIÉN RESPONDE POR LA PROMESA</div><h1>UNA PERSONA<br><em>conserva la decisión.</em></h1><div class="human-photo"><img src="img/proceso-3.jpg" alt="Ilustración conceptual de revisión por técnicos"><span>ILUSTRACIÓN CONCEPTUAL · NO ES UNA INSTALACIÓN REAL</span></div><div class="human-controls"><div><b>01</b><h2>PROTEGER</h2><p>Consentimiento y ruta borrada.</p></div><div><b>02</b><h2>SUPERVISAR</h2><p>El técnico aprueba, ajusta o bloquea.</p></div><div><b>03</b><h2>DETENER</h2><p>Cinco gatillos de suspensión.</p></div></div><div class="data-note">Legalidad, garantía y financiamiento: respuesta humana por escrito.</div>'''
 if k=='economia':return '''<div class="eyebrow">DECISIÓN ECONÓMICA / EL ESTIMADOR, NO EL TALLER</div><h1>EL PILOTO DEBE JUSTIFICAR<br><em>la inversión.</em></h1><div class="economic-hero"><strong>+3,0<span>pp</span></strong><h2>de agendamiento<br>para cubrir el costo</h2><p>Equilibrio aproximado.<br>Condicionado a los supuestos del informe.</p></div><div class="economic-cards"><div><span>INVERSIÓN · PRIMER AÑO</span><strong>$9,0 <small>M</small></strong></div><div class="accent"><span>ESCENARIO · +5 PP</span><strong>68<small>%</small></strong><p>Retorno estimado; no medido.</p></div></div><div class="data-note">A/B propuesto: detecta +15 pp. Revisar potencia para el equilibrio de +3 pp.</div>'''
 if k=='cierre':return '''<div class="closing-bg"><img src="img/cierre-premium.jpg" alt="Ilustración conceptual del producto"></div><div class="eyebrow">RECOMENDACIÓN / IMPLEMENTAR CON AJUSTES</div><h1>UNA PROMESA QUE<br><em>se puede comprobar.</em></h1><div class="closing-v2"><div><b>01</b><span>Retirar la cifra<br>genérica</span></div><div><b>02</b><span>Medir el efecto<br>con un A/B</span></div><div><b>03</b><span>Verificar antes<br>de escalar</span></div></div><div class="closing-condition">Estimación transparente · Telemetría · Viabilidad técnica y regulatoria</div><div class="illust">Ilustración conceptual del producto</div>'''
 return base(s)

